return {
    setSetting = function(p1, p2, p3) -- setSetting | line: 1
        if not p2 or p3 == nil or type(p2) ~= "string" then
            error("setSetting had invalid parameters.\nP1 - settingName: string\nP2 - settingValue: unknown", 2)
        end

        local v1 = "_" .. p2
        local v2 = p1[v1] == nil
        local v3 = if not v2 then type(p1[v1]) == "function" else nil

        if v2 or v3 then
            if p1[v1] ~= nil then
                error("Attempt to index setting " .. p2 .. " which is not an editable field.")
            else
                error("Attempt to index setting " .. p2 .. " which is not a valid setting!")
            end
        else
            p1[v1] = p3
        end
    end
}
